//! `/v1/webhook-sources` (AEGIS ADR-157 D4): a tenant registers a signed
//! sender and the workflow its deliveries start. The source's secret is
//! generated by AEGIS, kept in the tenant's own secret store, and answered
//! once, on creation or rotation, for the sender's settings.

use std::sync::Arc;

use axum::{
    extract::{Extension, Path, State},
    http::StatusCode,
    response::IntoResponse,
    Json,
};
use serde::Deserialize;
use serde_json::json;

use crate::daemon::state::AppState;
use aegis_orchestrator_core::application::webhook_source_service::{
    WebhookSourceError, WebhookSourceService,
};
use aegis_orchestrator_core::domain::iam::UserIdentity;
use aegis_orchestrator_core::domain::shared_kernel::TenantId;
use aegis_orchestrator_core::domain::webhook_source::{WebhookSource, WebhookSourceSpec};

type Answer = (StatusCode, Json<serde_json::Value>);

fn service(state: &AppState) -> Result<Arc<WebhookSourceService>, Answer> {
    state.webhook_sources.clone().ok_or((
        StatusCode::SERVICE_UNAVAILABLE,
        Json(json!({ "error": "unavailable", "message": "webhook sources need the orchestrator's database" })),
    ))
}

fn refused(e: WebhookSourceError) -> Answer {
    let status = match e {
        WebhookSourceError::Invalid(_) => StatusCode::BAD_REQUEST,
        WebhookSourceError::NotFound(_) => StatusCode::NOT_FOUND,
        WebhookSourceError::Unavailable(_) | WebhookSourceError::Repository(_) => {
            StatusCode::SERVICE_UNAVAILABLE
        }
    };
    (
        status,
        Json(json!({ "error": "webhook_source", "message": e.to_string() })),
    )
}

fn view(s: &WebhookSource) -> serde_json::Value {
    json!({
        "name": s.name,
        "url_path": format!("/v1/webhooks/{}", s.name),
        "workflow": s.spec.workflow,
        "events": s.spec.events,
        "event_header": s.spec.event_header,
        "when": s.spec.when,
        "inputs": s.spec.inputs,
        "owner": s.owner.sub,
        "created_by": s.created_by,
        "created_at": s.created_at.to_rfc3339(),
    })
}

#[derive(Debug, Deserialize)]
pub(crate) struct RegisterBody {
    name: String,
    #[serde(flatten)]
    spec: WebhookSourceSpec,
}

pub(crate) async fn list_webhook_sources_handler(
    State(state): State<Arc<AppState>>,
    Extension(tenant): Extension<TenantId>,
) -> Result<impl IntoResponse, Answer> {
    let list = service(&state)?.list(&tenant).await.map_err(refused)?;
    Ok(Json(json!(list.iter().map(view).collect::<Vec<_>>())))
}

/// Register or update a source. A new source's secret is in the answer, once.
pub(crate) async fn register_webhook_source_handler(
    State(state): State<Arc<AppState>>,
    Extension(tenant): Extension<TenantId>,
    Extension(identity): Extension<UserIdentity>,
    Json(body): Json<RegisterBody>,
) -> Result<impl IntoResponse, Answer> {
    let (saved, secret) = service(&state)?
        .register(&tenant, &body.name, body.spec, &identity)
        .await
        .map_err(refused)?;
    let mut answer = view(&saved);
    if let Some(secret) = secret {
        answer["secret"] = json!(secret);
        answer["secret_note"] =
            json!("Shown once. Set it as the sender's webhook secret; AEGIS keeps it in your secret store.");
    }
    Ok((StatusCode::OK, Json(answer)))
}

pub(crate) async fn get_webhook_source_handler(
    State(state): State<Arc<AppState>>,
    Extension(tenant): Extension<TenantId>,
    Path(name): Path<String>,
) -> Result<impl IntoResponse, Answer> {
    let s = service(&state)?
        .get(&tenant, &name)
        .await
        .map_err(refused)?;
    Ok(Json(view(&s)))
}

pub(crate) async fn delete_webhook_source_handler(
    State(state): State<Arc<AppState>>,
    Extension(tenant): Extension<TenantId>,
    Path(name): Path<String>,
) -> Result<impl IntoResponse, Answer> {
    service(&state)?
        .delete(&tenant, &name)
        .await
        .map_err(refused)?;
    Ok(StatusCode::NO_CONTENT)
}

/// A new secret, answered once; the old one stops verifying.
pub(crate) async fn rotate_webhook_source_secret_handler(
    State(state): State<Arc<AppState>>,
    Extension(tenant): Extension<TenantId>,
    Path(name): Path<String>,
) -> Result<impl IntoResponse, Answer> {
    let secret = service(&state)?
        .rotate_secret(&tenant, &name)
        .await
        .map_err(refused)?;
    Ok(Json(json!({ "name": name, "secret": secret,
        "secret_note": "Shown once. Set it as the sender's webhook secret; the previous one no longer verifies." })))
}
